import type { ComponentProps, ReactElement } from "react";
import { cn } from "@/registry/default/lib/utils";
import type { AgentAnnouncerController } from "./hooks/use-agent-announcer";

export type AgentAnnouncerProps = Omit<
  ComponentProps<"span">,
  "children" | "role"
> & {
  announcer: AgentAnnouncerController;
};

/** The conversation's one status region. Render it once, outside the scrolling log. */
export function AgentAnnouncer({
  announcer,
  className,
  ...props
}: AgentAnnouncerProps): ReactElement {
  return (
    <span
      aria-atomic="true"
      aria-live="polite"
      data-slot="agent-announcer"
      role="status"
      className={cn("sr-only", className)}
      {...props}
    >
      {announcer.message}
    </span>
  );
}

"use client";

import {
  CheckIcon,
  CircleAlertIcon,
  InfoIcon,
  Loader2Icon,
  XIcon,
} from "lucide-react";
import {
  type ComponentProps,
  type ReactElement,
  useEffect,
  useId,
  useRef,
} from "react";
import { cn } from "@/registry/default/lib/utils";
import { Badge } from "@/registry/default/ui/badge";
import { Button } from "@/registry/default/ui/button";
import {
  Card,
  CardFrame,
  CardFrameFooter,
  CardPanel,
} from "@/registry/default/ui/card";
import { useAgentPendingChoice } from "./hooks/use-agent-pending-choice";
import {
  type AgentApprovalDecision,
  type AgentApprovalGroupItem,
  type AgentApprovalPrompt,
  type AgentApprovalState,
  getAgentApprovalGroupShared,
  getAgentApprovalState,
} from "./lib/get-agent-approval-state";

type AgentApprovalBaseProps = Omit<
  ComponentProps<typeof CardFrame>,
  "children"
> & {
  /** Called with the person's answer. Return a promise to show the card responding until it settles; a rejection shows the error. */
  onRespond: (decision: AgentApprovalDecision) => void | Promise<void>;
  /** The answer your agent runtime recorded. Set it to show the resolved state. */
  decision?: AgentApprovalDecision | null;
  /** An answer is on its way through your runtime. The card also responds while `onRespond`'s promise runs. */
  responding?: boolean;
  /** The last answer didn't land. The card also shows an error when `onRespond`'s promise rejects. */
  error?: boolean;
  /** Blocks answering, for example while another turn is running. */
  disabled?: boolean;
  /** Announces the error label when `onRespond` rejects. Pass `announcer.announce`. */
  announce?: (message: string) => void;
};

type AgentApprovalFooterLabels = {
  approve: string;
  deny: string;
  approved: string;
  denied: string;
  error: string;
  hint?: string;
};

function useAgentApproval({
  onRespond,
  decision,
  responding = false,
  error = false,
  errorLabel,
  announce,
}: Pick<
  AgentApprovalBaseProps,
  "onRespond" | "decision" | "responding" | "error" | "announce"
> & { errorLabel: string }) {
  const { failed, pending, run } =
    useAgentPendingChoice<AgentApprovalDecision>();
  const state = getAgentApprovalState({
    decision,
    error: error || failed,
    responding: responding || pending !== null,
  });
  const respond = async (choice: AgentApprovalDecision): Promise<void> => {
    const outcome = await run(choice, () => onRespond(choice));
    if (outcome === "failed") announce?.(errorLabel);
  };
  return { pending, respond, state };
}

function AgentApprovalPromptBody({
  prompt,
  questionId,
  showQuestion = true,
}: {
  prompt: AgentApprovalPrompt;
  questionId?: string;
  showQuestion?: boolean;
}): ReactElement {
  return (
    <div className="flex flex-col gap-3" data-slot="agent-approval-prompt">
      <div className="flex flex-col gap-1.5">
        {showQuestion && (
          <p
            className="font-medium text-foreground text-sm"
            data-slot="agent-approval-question"
            id={questionId}
          >
            {prompt.question}
          </p>
        )}
        {prompt.context && (
          <p className="flex items-start gap-1.5 text-muted-foreground text-xs">
            <span className="flex h-lh shrink-0 items-center">
              <InfoIcon aria-hidden="true" className="size-3.5" />
            </span>
            {prompt.context}
          </p>
        )}
        {prompt.details?.length ? (
          <ul className="flex list-disc flex-col gap-0.5 ps-4 text-muted-foreground text-xs">
            {prompt.details.map((detail, index) => (
              <li key={`${index}-${detail}`}>{detail}</li>
            ))}
          </ul>
        ) : null}
      </div>
      {prompt.badge && (
        <Badge className="self-start" variant="secondary">
          {prompt.badge}
        </Badge>
      )}
    </div>
  );
}

function AgentApprovalFooter({
  state,
  pending,
  disabled,
  labels,
  onChoose,
}: {
  state: AgentApprovalState;
  pending: AgentApprovalDecision | null;
  disabled: boolean;
  labels: AgentApprovalFooterLabels;
  onChoose: (decision: AgentApprovalDecision) => void;
}): ReactElement {
  const statusRef = useRef<HTMLParagraphElement>(null);
  const approveRef = useRef<HTMLButtonElement>(null);
  const denyRef = useRef<HTMLButtonElement>(null);
  const hadFocusRef = useRef(false);
  const lastChoiceRef = useRef<AgentApprovalDecision>("approved");
  const resolved = state === "approved" || state === "denied";
  const blocked = disabled || state === "responding";

  // Answering disables, then removes, the focused button. Once the card settles,
  // hand focus to the resolved line, or back to the button after an error.
  useEffect(() => {
    if (!hadFocusRef.current || state === "responding") return;
    const active = document.activeElement;
    if (active && active !== document.body) return;
    if (state === "approved" || state === "denied") statusRef.current?.focus();
    else if (lastChoiceRef.current === "denied") denyRef.current?.focus();
    else approveRef.current?.focus();
  }, [state]);

  const choose = (choice: AgentApprovalDecision): void => {
    lastChoiceRef.current = choice;
    onChoose(choice);
  };

  return (
    <CardFrameFooter
      className="flex flex-wrap items-center justify-end gap-2 px-3 py-2"
      data-slot="agent-approval-footer"
      onBlur={(event) => {
        // No related target means focus went nowhere, as when the button was disabled or removed.
        if (
          event.relatedTarget &&
          !event.currentTarget.contains(event.relatedTarget)
        )
          hadFocusRef.current = false;
      }}
      onFocus={() => {
        hadFocusRef.current = true;
      }}
    >
      {resolved ? (
        <p
          className="me-auto flex min-h-7 items-center gap-1.5 text-muted-foreground text-xs outline-none"
          data-slot="agent-approval-status"
          ref={statusRef}
          tabIndex={-1}
        >
          {state === "approved" ? (
            <>
              <CheckIcon aria-hidden="true" className="size-3.5 shrink-0" />
              {labels.approved}
            </>
          ) : (
            <>
              <XIcon aria-hidden="true" className="size-3.5 shrink-0" />
              {labels.denied}
            </>
          )}
        </p>
      ) : (
        <>
          {state === "error" ? (
            <p
              className="me-auto flex items-center gap-1.5 text-destructive-foreground text-xs"
              data-slot="agent-approval-status"
            >
              <CircleAlertIcon
                aria-hidden="true"
                className="size-3.5 shrink-0"
              />
              {labels.error}
            </p>
          ) : (
            labels.hint && (
              <p
                className="me-auto text-muted-foreground text-xs"
                data-slot="agent-approval-hint"
              >
                {labels.hint}
              </p>
            )
          )}
          <div className="flex gap-2">
            <Button
              data-slot="agent-approval-deny"
              disabled={blocked}
              onClick={() => choose("denied")}
              ref={denyRef}
              size="xs"
              variant="ghost"
            >
              {pending === "denied" && <AgentApprovalPendingIcon />}
              {labels.deny}
            </Button>
            <Button
              data-slot="agent-approval-approve"
              disabled={blocked}
              onClick={() => choose("approved")}
              ref={approveRef}
              size="xs"
            >
              {pending === "approved" && <AgentApprovalPendingIcon />}
              {labels.approve}
            </Button>
          </div>
        </>
      )}
    </CardFrameFooter>
  );
}

function AgentApprovalPendingIcon(): ReactElement {
  return (
    <Loader2Icon aria-hidden="true" className="motion-safe:animate-spin" />
  );
}

export type AgentApprovalCardLabels = {
  /** Default approve verb, such as “Confirm”. `prompt.approveLabel` overrides it. */
  approve: string;
  /** Default deny verb, such as “Cancel”. `prompt.denyLabel` overrides it. */
  deny: string;
  /** The resolved line after approving, such as “Approved”. */
  approved: string;
  /** The resolved line after denying, such as “Skipped”. */
  denied: string;
  /** Shown beside the actions when the answer didn't land. */
  error: string;
  /** Optional line beside the actions, such as how to request changes. */
  hint?: string;
};

export type AgentApprovalCardProps = AgentApprovalBaseProps & {
  prompt: AgentApprovalPrompt;
  labels: AgentApprovalCardLabels;
};

/** Asks the person to approve one agent action, then shows how it resolved. */
export function AgentApprovalCard({
  prompt,
  labels,
  onRespond,
  decision,
  responding,
  error,
  disabled = false,
  announce,
  className,
  ...props
}: AgentApprovalCardProps): ReactElement {
  const questionId = useId();
  const approval = useAgentApproval({
    announce,
    decision,
    error,
    errorLabel: labels.error,
    onRespond,
    responding,
  });

  return (
    <CardFrame
      aria-labelledby={questionId}
      className={cn("w-full", className)}
      data-slot="agent-approval-card"
      data-state={approval.state}
      role="group"
      {...props}
    >
      <Card>
        <CardPanel className="p-4">
          <AgentApprovalPromptBody prompt={prompt} questionId={questionId} />
        </CardPanel>
      </Card>
      <AgentApprovalFooter
        disabled={disabled}
        labels={{
          ...labels,
          approve: prompt.approveLabel ?? labels.approve,
          deny: prompt.denyLabel ?? labels.deny,
        }}
        onChoose={(choice) => void approval.respond(choice)}
        pending={approval.pending}
        state={approval.state}
      />
    </CardFrame>
  );
}

export type AgentApprovalGroupCardLabels = {
  /** Approves every item, such as “Approve all”. A verb every item shares replaces it. */
  approveAll: string;
  /** Denies every item, such as “Skip all”. */
  skipAll: string;
  /** The resolved line after approving all. */
  approved: string;
  /** The resolved line after skipping all. */
  denied: string;
  /** Shown beside the actions when the answer didn't land. */
  error: string;
  /** Optional line beside the actions, such as “Skip first to request changes”. */
  hint?: string;
};

export type AgentApprovalGroupCardProps = AgentApprovalBaseProps & {
  items: readonly AgentApprovalGroupItem[];
  labels: AgentApprovalGroupCardLabels;
};

/**
 * Asks the person to approve several agent actions at once. Every item gets the same answer:
 * `onRespond` is called once, and your host answers each item.
 */
export function AgentApprovalGroupCard({
  items,
  labels,
  onRespond,
  decision,
  responding,
  error,
  disabled = false,
  announce,
  className,
  ...props
}: AgentApprovalGroupCardProps): ReactElement | null {
  const questionId = useId();
  const approval = useAgentApproval({
    announce,
    decision,
    error,
    errorLabel: labels.error,
    onRespond,
    responding,
  });
  if (items.length === 0) return null;
  const shared = getAgentApprovalGroupShared(items);

  return (
    <CardFrame
      aria-labelledby={shared.question ? questionId : undefined}
      className={cn("w-full", className)}
      data-slot="agent-approval-group-card"
      data-state={approval.state}
      // Without a shared question there's no name for the group; each item names itself.
      role={shared.question ? "group" : undefined}
      {...props}
    >
      <Card>
        <CardPanel className="flex flex-col gap-4 p-4">
          {shared.question && (
            <p
              className="font-medium text-foreground text-sm"
              data-slot="agent-approval-question"
              id={questionId}
            >
              {shared.question}
            </p>
          )}
          <ul className="flex flex-col gap-4">
            {items.map((item) => (
              <li data-slot="agent-approval-group-item" key={item.id}>
                <AgentApprovalPromptBody
                  prompt={item.prompt}
                  showQuestion={!shared.question}
                />
              </li>
            ))}
          </ul>
        </CardPanel>
      </Card>
      <AgentApprovalFooter
        disabled={disabled}
        labels={{
          ...labels,
          approve: shared.approveLabel ?? labels.approveAll,
          deny: labels.skipAll,
        }}
        onChoose={(choice) => void approval.respond(choice)}
        pending={approval.pending}
        state={approval.state}
      />
    </CardFrame>
  );
}

"use client";

import type { ReactElement, UIEvent } from "react";
import { cn } from "@/registry/default/lib/utils";
import {
  ChatConversation,
  type ChatConversationProps,
} from "../chat/chat-conversation";
import {
  AGENT_SCROLL_OFFSET_VAR,
  getAgentScrollOffset,
} from "./lib/get-agent-scroll-offset";

export type AgentConversationProps = ChatConversationProps;

export function AgentConversation({
  scroll,
  live = "off",
  contentClassName,
  ...props
}: AgentConversationProps): ReactElement {
  const onScroll = (event: UIEvent<HTMLDivElement>): void => {
    event.currentTarget.style.setProperty(
      AGENT_SCROLL_OFFSET_VAR,
      getAgentScrollOffset(event.currentTarget.scrollTop),
    );
    scroll.onScroll(event);
  };

  return (
    <ChatConversation
      data-slot="agent-conversation"
      scroll={{ ...scroll, onScroll }}
      live={live}
      contentClassName={cn(
        // Inside a popover crossfade snapshot ([data-previous]), keep the reader's place.
        // The variable is AGENT_SCROLL_OFFSET_VAR; Tailwind needs it spelled out here.
        "flex in-data-previous:-translate-y-(--agent-conversation-scroll-top) flex-col gap-6 pt-4",
        contentClassName,
      )}
      {...props}
    />
  );
}

"use client";

import { mergeProps } from "@base-ui/react/merge-props";
import { useRender } from "@base-ui/react/use-render";
import { CircleAlertIcon } from "lucide-react";
import type { ReactElement, ReactNode } from "react";
import { cn } from "@/registry/default/lib/utils";
import { Button } from "@/registry/default/ui/button";

export type AgentErrorRecoveryProps = useRender.ComponentProps<"div"> & {
  /** What went wrong, in your words, such as “The connection dropped.” */
  children: ReactNode;
  /** Names the retry action, such as “Try again”. */
  retryLabel?: string;
  /** Runs the turn again. Without it, the retry action isn't rendered. */
  onRetry?: () => void;
  /** Names the check-status action, such as “Check status”, for a turn that may have changed something. */
  checkStatusLabel?: string;
  /** Finds out whether the failed turn finished. Without it, the action isn't rendered. */
  onCheckStatus?: () => void;
};

/**
 * Shows a failed turn and the recovery your host offers. Your host decides what failed
 * and which action fits; remove it once recovery starts.
 */
export function AgentErrorRecovery({
  children,
  retryLabel,
  onRetry,
  checkStatusLabel,
  onCheckStatus,
  className,
  render,
  ...props
}: AgentErrorRecoveryProps): ReactElement {
  const actions = [
    { label: checkStatusLabel, onClick: onCheckStatus, slot: "check-status" },
    { label: retryLabel, onClick: onRetry, slot: "retry" },
  ].filter((action) => action.label && action.onClick);

  const defaultProps = {
    children: (
      <>
        <div
          className="flex items-start gap-1.5 text-muted-foreground text-sm"
          data-slot="agent-error-recovery-message"
        >
          <span className="flex h-lh shrink-0 items-center">
            <CircleAlertIcon
              aria-hidden="true"
              className="size-4 text-destructive-foreground"
            />
          </span>
          <div>{children}</div>
        </div>
        {actions.length > 0 && (
          <div
            className="flex flex-wrap gap-2"
            data-slot="agent-error-recovery-actions"
          >
            {actions.map((action) => (
              <Button
                data-slot={`agent-error-recovery-${action.slot}`}
                key={action.slot}
                onClick={action.onClick}
                size="xs"
                variant="outline"
              >
                {action.label}
              </Button>
            ))}
          </div>
        )}
      </>
    ),
    className: cn("flex flex-col items-start gap-2", className),
    "data-slot": "agent-error-recovery",
  };

  return useRender({
    defaultTagName: "div",
    props: mergeProps<"div">(defaultProps, props),
    render,
  });
}

"use client";

import type { Toolbar as ToolbarPrimitive } from "@base-ui/react/toolbar";
import { CheckIcon, CopyIcon, PencilIcon } from "lucide-react";
import type { ReactElement, ReactNode } from "react";
import { useCopyToClipboard } from "@/registry/default/hooks/use-copy-to-clipboard";
import { cn } from "@/registry/default/lib/utils";
import { Button, type ButtonProps } from "@/registry/default/ui/button";
import { Toolbar, ToolbarButton } from "@/registry/default/ui/toolbar";
import {
  Tooltip,
  TooltipPopup,
  TooltipTrigger,
} from "@/registry/default/ui/tooltip";

export type AgentMessageActionsProps = Omit<
  ToolbarPrimitive.Root.Props,
  "aria-label"
> & {
  label: string;
};

export function AgentMessageActions({
  label,
  className,
  ...props
}: AgentMessageActionsProps): ReactElement {
  return (
    <Toolbar
      aria-label={label}
      data-slot="agent-message-actions"
      className={cn(
        "w-fit gap-0.5 rounded-none border-0 bg-transparent p-0 transition-opacity motion-reduce:transition-none",
        // Inside a message on a fine pointer, hide until the message is hovered or focused,
        // or a popup from an action is open. Coarse pointers always show the actions.
        "pointer-fine:in-[[data-slot=agent-message]:not(:hover):not(:focus-within):not([data-actions-visible]):not(:has([data-popup-open]))]:opacity-0",
        className,
      )}
      {...props}
    />
  );
}

export type AgentMessageActionProps = Omit<
  ButtonProps,
  "aria-label" | "children" | "size" | "variant"
> & {
  label: string;
  children: ReactNode;
  /** Tooltip content. Defaults to `label`. */
  tooltip?: ReactNode;
};

export function AgentMessageAction({
  label,
  children,
  tooltip = label,
  onClick,
  render,
  disabled,
  className,
  ...props
}: AgentMessageActionProps): ReactElement {
  // An action that can't do anything is a real disabled button, never aria-disabled alone.
  const inactive = disabled || (!onClick && !render);
  return (
    <Tooltip>
      <TooltipTrigger
        render={
          <ToolbarButton
            disabled={inactive}
            focusableWhenDisabled={false}
            render={
              <Button
                aria-label={label}
                className={cn(
                  "text-muted-foreground hover:text-foreground",
                  className,
                )}
                data-slot="agent-message-action"
                disabled={inactive}
                onClick={onClick}
                render={render}
                size="icon-xs"
                variant="ghost"
                {...props}
              />
            }
          />
        }
      >
        {children}
      </TooltipTrigger>
      <TooltipPopup>{tooltip}</TooltipPopup>
    </Tooltip>
  );
}

export type AgentMessageCopyActionProps = Omit<
  AgentMessageActionProps,
  "children" | "onClick" | "render" | "tooltip"
> & {
  text: string;
  copiedLabel: string;
  /** Called after the text reaches the clipboard. Announce `copiedLabel` here; the button's name stays `label`. */
  onCopy?: () => void;
};

export function AgentMessageCopyAction({
  text,
  label,
  copiedLabel,
  onCopy,
  disabled,
  ...props
}: AgentMessageCopyActionProps): ReactElement {
  const { copyToClipboard, isCopied } = useCopyToClipboard({ onCopy });
  return (
    <AgentMessageAction
      data-copied={isCopied || undefined}
      disabled={disabled || !text}
      label={label}
      tooltip={isCopied ? copiedLabel : label}
      onClick={() => copyToClipboard(text)}
      {...props}
    >
      {isCopied ? (
        <CheckIcon aria-hidden="true" />
      ) : (
        <CopyIcon aria-hidden="true" />
      )}
    </AgentMessageAction>
  );
}

export type AgentMessageEditActionProps = Omit<
  AgentMessageActionProps,
  "children" | "onClick" | "render"
> & {
  onEdit: () => void;
};

export function AgentMessageEditAction({
  onEdit,
  ...props
}: AgentMessageEditActionProps): ReactElement {
  return (
    <AgentMessageAction onClick={onEdit} {...props}>
      <PencilIcon aria-hidden="true" />
    </AgentMessageAction>
  );
}

import type { ReactElement, ReactNode } from "react";
import { ChatBubble } from "../chat/chat-bubble";
import {
  ChatMessageAvatar,
  ChatMessageContent,
  ChatMessageFooter,
  ChatMessageLayout,
  type ChatMessageLayoutProps,
} from "../chat/chat-message-layout";
import { ChatMessageText } from "../chat/chat-message-text";

export type AgentMessageProps = Omit<ChatMessageLayoutProps, "align"> & {
  from: "user" | "assistant";
  /** The agent's identity mark beside an assistant reply. Ignored on user messages. */
  avatar?: ReactNode;
  actions?: ReactNode;
  /** Keep actions shown instead of revealing them on hover and focus. */
  actionsAlwaysVisible?: boolean;
  footer?: ReactNode;
  streaming?: boolean;
};

export function AgentMessage({
  from,
  avatar,
  actions,
  actionsAlwaysVisible = false,
  footer,
  streaming,
  children,
  ...props
}: AgentMessageProps): ReactElement {
  const user = from === "user";
  const content =
    typeof children === "string" ? (
      <ChatMessageText text={children} />
    ) : (
      children
    );

  return (
    <ChatMessageLayout
      align={user ? "end" : "start"}
      data-slot="agent-message"
      data-from={from}
      data-actions-visible={actionsAlwaysVisible || undefined}
      {...props}
    >
      {!user && avatar && <ChatMessageAvatar>{avatar}</ChatMessageAvatar>}
      <ChatMessageContent streaming={streaming}>
        {user ? (
          <ChatBubble align="end" className="max-w-[83%]">
            {content}
          </ChatBubble>
        ) : (
          content
        )}
        {actions}
        {footer && <ChatMessageFooter>{footer}</ChatMessageFooter>}
      </ChatMessageContent>
    </ChatMessageLayout>
  );
}

"use client";

import type { Toolbar as ToolbarPrimitive } from "@base-ui/react/toolbar";
import {
  CheckIcon,
  CircleAlertIcon,
  Loader2Icon,
  PlusIcon,
  ThumbsDownIcon,
  ThumbsUpIcon,
} from "lucide-react";
import { type FormEvent, type ReactElement, useState } from "react";
import { cn } from "@/registry/default/lib/utils";
import { Button } from "@/registry/default/ui/button";
import {
  Dialog,
  DialogClose,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogPanel,
  DialogPopup,
  DialogTitle,
} from "@/registry/default/ui/dialog";
import { Field, FieldLabel } from "@/registry/default/ui/field";
import { Fieldset, FieldsetLegend } from "@/registry/default/ui/fieldset";
import { Form } from "@/registry/default/ui/form";
import { Textarea } from "@/registry/default/ui/textarea";
import { Toggle } from "@/registry/default/ui/toggle";
import { ToolbarGroup } from "@/registry/default/ui/toolbar";
import { AgentMessageAction } from "./agent-message-actions";
import { useAgentPendingChoice } from "./hooks/use-agent-pending-choice";
import {
  type AgentFeedbackRating,
  type AgentFeedbackValue,
  getAgentFeedbackAction,
  getAgentFeedbackSubmission,
} from "./lib/get-agent-feedback";

export type AgentResponseFeedbackReason = {
  value: string;
  label: string;
};

export type AgentResponseFeedbackLabels = {
  /** Names the thumbs-up button, such as “Good response”. */
  positive: string;
  /** Names the thumbs-down button, such as “Bad response”. */
  negative: string;
  dialogTitle: string;
  dialogDescription?: string;
  /** The legend over the reasons, such as “What went wrong?”. */
  reasons?: string;
  details: string;
  detailsPlaceholder?: string;
  cancel: string;
  submit: string;
  /** Announced when feedback is saved, such as “Thanks for your feedback”. */
  submitted: string;
  /** Shown and announced when saving fails. */
  error: string;
};

export type AgentResponseFeedbackProps = Omit<
  ToolbarPrimitive.Group.Props,
  "children"
> & {
  /** The rating to show. Controlled: update it once `onFeedback` resolves. */
  value: AgentFeedbackRating | null;
  /**
   * Saves feedback, or `null` when the person presses the shown rating again to clear it.
   * A rejection shows the error state; retrying is up to your host.
   */
  onFeedback: (feedback: AgentFeedbackValue | null) => void | Promise<void>;
  labels: AgentResponseFeedbackLabels;
  /** Reasons offered after a thumbs down. When given, one is required to submit. */
  reasons?: readonly AgentResponseFeedbackReason[];
  /** Caps the details field, so text is never cut after the person typed it. */
  detailsMaxLength?: number;
  disabled?: boolean;
  /** Announces the saved and error labels. Pass `announcer.announce`. */
  announce?: (message: string) => void;
};

/**
 * Thumbs up and down for a reply. A thumbs down asks for reasons and details first.
 * Place it inside `AgentMessageActions`.
 */
export function AgentResponseFeedback({
  value,
  onFeedback,
  labels,
  reasons = [],
  detailsMaxLength,
  disabled = false,
  announce,
  className,
  ...props
}: AgentResponseFeedbackProps): ReactElement {
  const { clearFailure, failed, pending, run } =
    useAgentPendingChoice<AgentFeedbackRating>();
  const [dialogOpen, setDialogOpen] = useState(false);
  const [selectedReasons, setSelectedReasons] = useState<string[]>([]);
  const [details, setDetails] = useState("");
  const submission = getAgentFeedbackSubmission({
    details,
    detailsMaxLength,
    reasons: selectedReasons,
    reasonsOffered: reasons.length > 0,
  });

  const save = async (
    rating: AgentFeedbackRating,
    feedback: AgentFeedbackValue | null,
  ): Promise<boolean> => {
    const outcome = await run(rating, () => onFeedback(feedback));
    if (outcome === "failed") announce?.(labels.error);
    if (outcome === "succeeded" && feedback) announce?.(labels.submitted);
    return outcome === "succeeded";
  };

  const rate = (next: AgentFeedbackRating): void => {
    if (pending) return;
    const action = getAgentFeedbackAction(value, next);
    if (action.type === "ask-details") {
      clearFailure();
      setDialogOpen(true);
    } else if (action.type === "clear") void save(next, null);
    else void save(next, action.feedback);
  };

  const submitDetails = async (
    event: FormEvent<HTMLFormElement>,
  ): Promise<void> => {
    event.preventDefault();
    if (!submission) return;
    if (await save("negative", submission)) setDialogOpen(false);
  };

  const ratings = [
    { icon: ThumbsUpIcon, label: labels.positive, rating: "positive" },
    { icon: ThumbsDownIcon, label: labels.negative, rating: "negative" },
  ] as const;

  return (
    <ToolbarGroup
      className={cn("gap-0.5", className)}
      data-slot="agent-response-feedback"
      data-state={pending ? "submitting" : failed ? "error" : "idle"}
      {...props}
    >
      {ratings.map(({ icon: Icon, label, rating }) => (
        <AgentMessageAction
          aria-pressed={value === rating}
          className="aria-pressed:bg-accent aria-pressed:text-foreground"
          disabled={disabled}
          key={rating}
          label={label}
          // Stays enabled while saving so focus isn't dropped; repeat presses are ignored.
          onClick={() => rate(rating)}
        >
          {pending === rating && !dialogOpen ? (
            <Loader2Icon
              aria-hidden="true"
              className="motion-safe:animate-spin"
            />
          ) : (
            <Icon aria-hidden="true" />
          )}
        </AgentMessageAction>
      ))}
      {failed && !dialogOpen && (
        <span
          className="flex items-center gap-1.5 px-1 text-destructive-foreground text-xs"
          data-slot="agent-response-feedback-error"
        >
          <CircleAlertIcon aria-hidden="true" className="size-3.5 shrink-0" />
          {labels.error}
        </span>
      )}
      <Dialog
        onOpenChange={(open) => {
          if (!pending) setDialogOpen(open);
        }}
        onOpenChangeComplete={(open) => {
          if (open) return;
          // Closing the form, saved or not, moves on from its failure.
          clearFailure();
          setSelectedReasons([]);
          setDetails("");
        }}
        open={dialogOpen}
      >
        <DialogPopup showCloseButton={false}>
          <DialogHeader>
            <DialogTitle>{labels.dialogTitle}</DialogTitle>
            {labels.dialogDescription && (
              <DialogDescription>{labels.dialogDescription}</DialogDescription>
            )}
          </DialogHeader>
          <Form
            className="contents"
            onSubmit={(event: FormEvent<HTMLFormElement>) =>
              void submitDetails(event)
            }
          >
            <DialogPanel className="flex flex-col gap-5">
              {reasons.length > 0 && (
                <Fieldset className="flex flex-col gap-2">
                  {labels.reasons && (
                    <FieldsetLegend className="font-medium text-sm">
                      {labels.reasons}
                    </FieldsetLegend>
                  )}
                  <div className="flex flex-wrap gap-2">
                    {reasons.map((reason) => {
                      const selected = selectedReasons.includes(reason.value);
                      return (
                        <Toggle
                          disabled={pending !== null}
                          key={reason.value}
                          onPressedChange={(pressed: boolean) =>
                            setSelectedReasons((current) =>
                              pressed
                                ? [...current, reason.value]
                                : current.filter(
                                    (item) => item !== reason.value,
                                  ),
                            )
                          }
                          pressed={selected}
                          size="sm"
                          variant="outline"
                        >
                          {selected ? (
                            <CheckIcon aria-hidden="true" />
                          ) : (
                            <PlusIcon aria-hidden="true" />
                          )}
                          {reason.label}
                        </Toggle>
                      );
                    })}
                  </div>
                </Fieldset>
              )}
              <Field>
                <FieldLabel>{labels.details}</FieldLabel>
                <Textarea
                  disabled={pending !== null}
                  maxLength={detailsMaxLength}
                  name="details"
                  onChange={(event) => setDetails(event.target.value)}
                  placeholder={labels.detailsPlaceholder}
                  value={details}
                />
              </Field>
              {failed && (
                <p
                  className="flex items-center gap-1.5 text-destructive-foreground text-sm"
                  data-slot="agent-response-feedback-error"
                >
                  <CircleAlertIcon
                    aria-hidden="true"
                    className="size-4 shrink-0"
                  />
                  {labels.error}
                </p>
              )}
            </DialogPanel>
            <DialogFooter>
              <DialogClose
                disabled={pending !== null}
                render={<Button variant="ghost" />}
              >
                {labels.cancel}
              </DialogClose>
              {/* Stays enabled while saving so focus isn't dropped; repeat submits are ignored. */}
              <Button disabled={!submission} type="submit">
                {pending === "negative" && (
                  <Loader2Icon
                    aria-hidden="true"
                    className="motion-safe:animate-spin"
                  />
                )}
                {labels.submit}
              </Button>
            </DialogFooter>
          </Form>
        </DialogPopup>
      </Dialog>
    </ToolbarGroup>
  );
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import {
  type AgentAnnouncementState,
  type AgentPhase,
  getAgentAnnouncement,
  getAgentAnnouncerMessage,
} from "../lib/get-agent-announcement";

export type AgentAnnouncerLabels = Partial<
  Record<Exclude<AgentPhase, "idle">, string>
>;

export type AgentAnnouncerOptions = {
  phase: AgentPhase;
  /** Localized text for each phase. A phase without a label is never announced. */
  labels: AgentAnnouncerLabels;
  /** Replaces the phase label, such as the error or the approval question. */
  detail?: string;
  /** Changing it starts a new baseline, so a switched conversation isn't replayed. */
  conversationId?: string;
};

export function useAgentAnnouncer({
  phase,
  labels,
  detail,
  conversationId,
}: AgentAnnouncerOptions) {
  const [message, setMessage] = useState("");
  const previousRef = useRef<AgentAnnouncementState | null>(null);
  const text = phase === "idle" ? "" : (detail ?? labels[phase] ?? "");

  useEffect(() => {
    const next = { conversationId, phase, text };
    const announcement = getAgentAnnouncement(previousRef.current, next);
    previousRef.current = next;
    if (announcement)
      setMessage((current) => getAgentAnnouncerMessage(current, announcement));
  }, [conversationId, phase, text]);

  /** Announce a one-off result, such as a copied message. */
  const announce = useCallback((value: string): void => {
    if (value)
      setMessage((current) => getAgentAnnouncerMessage(current, value));
  }, []);

  return { announce, message };
}

export type AgentAnnouncerController = ReturnType<typeof useAgentAnnouncer>;

"use client";

import { useCallback, useRef, useState } from "react";

export type AgentPendingChoiceOutcome = "succeeded" | "failed" | "ignored";

/**
 * Tracks the choice whose host callback is still running, and whether the last one failed.
 * A callback that returns nothing settles at once; a throw or a rejected promise sets `failed`.
 */
export function useAgentPendingChoice<T>() {
  const [pending, setPending] = useState<T | null>(null);
  const [failed, setFailed] = useState(false);
  const runningRef = useRef(false);

  /** Runs the callback for a choice. Another choice is ignored while one is running. */
  const run = useCallback(
    async (
      choice: T,
      callback: () => void | Promise<void>,
    ): Promise<AgentPendingChoiceOutcome> => {
      if (runningRef.current) return "ignored";
      setFailed(false);
      let result: void | Promise<void>;
      try {
        result = callback();
      } catch {
        setFailed(true);
        return "failed";
      }
      // Only a promise shows as pending, so a synchronous answer never flashes a spinner.
      if (!result) return "succeeded";
      runningRef.current = true;
      setPending(choice);
      try {
        await result;
        return "succeeded";
      } catch {
        setFailed(true);
        return "failed";
      } finally {
        runningRef.current = false;
        setPending(null);
      }
    },
    [],
  );

  /** Clears a failure the person has moved on from, such as by closing a form. */
  const clearFailure = useCallback(() => setFailed(false), []);

  return { clearFailure, failed, pending, run };
}

"use client";

import { useMediaQuery } from "@/registry/default/hooks/use-media-query";

/**
 * The agent family's reduced-motion check for motion timed in JavaScript, such as an
 * exit delay or an animation loop. CSS transitions use `motion-reduce:` variants instead.
 */
export function useAgentReducedMotion(): boolean {
  return useMediaQuery("(prefers-reduced-motion: reduce)");
}

export type AgentPhase =
  | "idle"
  | "thinking"
  | "working"
  | "approval"
  | "done"
  | "stopped"
  | "failed";

export type AgentAnnouncementState = {
  phase: AgentPhase;
  /** What this phase would say: a phase label, or a detail such as the error. */
  text: string;
  conversationId?: string;
};

function isBusy(phase: AgentPhase): boolean {
  return phase === "thinking" || phase === "working";
}

export function getAgentAnnouncement(
  previous: AgentAnnouncementState | null,
  next: AgentAnnouncementState,
): string {
  // A new mount or conversation only records a baseline; its state isn't replayed.
  if (previous === null || previous.conversationId !== next.conversationId)
    return "";
  if (next.phase !== previous.phase) {
    if (isBusy(next.phase) && isBusy(previous.phase)) return "";
    return next.text;
  }
  // Busy text is progress, streamed or not: only settled phases re-announce new text.
  if (isBusy(next.phase) || next.text === previous.text) return "";
  return next.text;
}

const REPEAT_MARK = " ";

/** Live regions skip unchanged content, so a repeat toggles a trailing no-break space. */
export function getAgentAnnouncerMessage(
  current: string,
  text: string,
): string {
  if (current === text) return `${text}${REPEAT_MARK}`;
  return text;
}

export type AgentApprovalDecision = "approved" | "denied";

export type AgentApprovalState =
  | "idle"
  | "responding"
  | AgentApprovalDecision
  | "error";

export type AgentApprovalStateInput = {
  /** The answer the agent runtime recorded. Once set, the question is resolved. */
  decision?: AgentApprovalDecision | null;
  /** An answer is on its way and hasn't landed yet. */
  responding?: boolean;
  /** The last answer didn't land. The question can be answered again. */
  error?: boolean;
};

export function getAgentApprovalState({
  decision,
  responding = false,
  error = false,
}: AgentApprovalStateInput): AgentApprovalState {
  // The runtime is the source of truth: a recorded decision outlasts any local attempt.
  if (decision) return decision;
  if (responding) return "responding";
  if (error) return "error";
  return "idle";
}

/** Everything one approval says. All wording comes from the host. */
export type AgentApprovalPrompt = {
  question: string;
  /** The question a group card asks once when every item asks `question`, such as its plural. */
  sharedQuestion?: string;
  /** One line on what happens, such as the affected booking. */
  context?: string;
  /** Lines listed under the question, such as the fields that change. */
  details?: readonly string[];
  /** A short tag, such as the tool or the resource. */
  badge?: string;
  /** The approve verb for this action, such as “Cancel booking”. Defaults to the card's label. */
  approveLabel?: string;
  /** The deny verb for this action. Defaults to the card's label. */
  denyLabel?: string;
};

export type AgentApprovalGroupItem = {
  id: string;
  prompt: AgentApprovalPrompt;
};

export type AgentApprovalGroupShared = {
  /** Set when every item asks the same question: the group asks it once. */
  question?: string;
  /** Set when every item uses the same approve verb: approve-all uses it. */
  approveLabel?: string;
};

function allSame<T>(
  items: readonly AgentApprovalGroupItem[],
  pick: (prompt: AgentApprovalPrompt) => T,
): boolean {
  const first = items[0];
  return (
    !!first && items.every((item) => pick(item.prompt) === pick(first.prompt))
  );
}

export function getAgentApprovalGroupShared(
  items: readonly AgentApprovalGroupItem[],
): AgentApprovalGroupShared {
  const first = items[0]?.prompt;
  if (!first) return {};
  const shared: AgentApprovalGroupShared = {};
  if (allSame(items, (prompt) => prompt.question))
    shared.question = first.sharedQuestion ?? first.question;
  if (allSame(items, (prompt) => prompt.approveLabel) && first.approveLabel)
    shared.approveLabel = first.approveLabel;
  return shared;
}

export type AgentFeedbackRating = "positive" | "negative";

export type AgentFeedbackValue = {
  rating: AgentFeedbackRating;
  /** The values of the reasons the person picked. Empty for a thumbs up. */
  reasons: string[];
  /** Trimmed and capped at the details limit. */
  details: string;
};

export type AgentFeedbackAction =
  | { type: "submit"; feedback: AgentFeedbackValue }
  | { type: "clear" }
  | { type: "ask-details" };

/** What pressing a rating does, given the rating already shown. */
export function getAgentFeedbackAction(
  current: AgentFeedbackRating | null,
  next: AgentFeedbackRating,
): AgentFeedbackAction {
  if (current === next) return { type: "clear" };
  if (next === "negative") return { type: "ask-details" };
  return {
    type: "submit",
    feedback: { details: "", rating: "positive", reasons: [] },
  };
}

export type AgentFeedbackDraft = {
  reasons: readonly string[];
  details: string;
  /** Whether the form offered reasons to pick from. */
  reasonsOffered: boolean;
  detailsMaxLength?: number;
};

/** The thumbs-down feedback a draft submits, or null while it can't be submitted yet. */
export function getAgentFeedbackSubmission({
  reasons,
  details,
  reasonsOffered,
  detailsMaxLength,
}: AgentFeedbackDraft): AgentFeedbackValue | null {
  if (reasonsOffered && reasons.length === 0) return null;
  return {
    rating: "negative",
    reasons: [...reasons],
    details: details.trim().slice(0, detailsMaxLength),
  };
}

export const AGENT_SCROLL_OFFSET_VAR = "--agent-conversation-scroll-top";

/**
 * Base UI popover viewports crossfade a cloned snapshot of the outgoing content,
 * and a clone keeps attributes but not scroll position. Written to the viewport's
 * inline style, this offset travels with the clone so the transcript can be
 * translated back to where the reader was.
 */
export function getAgentScrollOffset(scrollTop: number): string {
  return `${Math.max(0, scrollTop)}px`;
}
